import type { Column, Typed } from '../Column'

type Password2ColumnType<Type extends string = string, Default extends Type = Type> = Column<Type, Default>

/**
 * A Column for an encrypted password type field.
 *
 * @see https://docs.servicenow.com/csh?topicname=table-api-now-ts.html&version=latest
 *
 * @group Table/Columns
 */
export function Password2Column<
    const Type extends string,
    const Default extends Type,
    const C extends Password2ColumnType<Type, Default>,
>(config: C & Password2ColumnType<Type, Default>) {
    return config as Typed<Type, C>
}
